using System;

class Person
{
    // Property
    public string Name { get; set; }

    // Method
    public void SayHello()
    {
        Console.WriteLine($"Hello, my name is {Name}.");
    }
}

class Program
{
    static void Main()
    {
        Person person = new Person();
        person.Name = "Alice";
        person.SayHello();
    }
}
